/*
 * 증권의 이름가져오기
 */
/**
 * @method
 * @name fn_getSecuGrpNm
 * @description desc
 * @param {string} sid desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getSecuGrpNm = function(sid) {
    var snm = "";
    if (sid == "ST") {
        snm = "주권";
    } else if (sid == "MF") {
        snm = "투자";
    } else if (sid == "RT") {
        snm = "부동산투자";
    } else if (sid == "SC") {
        snm = "선박투자";
    } else if (sid == "IF") {
        snm = "사회간접자본투융자회사";
    } else if (sid == "DR") {
        snm = "주식예탁증서";
    } else if (sid == "SW") {
        snm = "신주인수권증권";
    } else if (sid == "SR") {
        snm = "신주인수권증서";
    } else if (sid == "EW") {
        snm = "ELW";
    } else if (sid == "EF") {
        snm = "ETF";
    } else if (sid == "BC") {
        snm = "수익증권";
    } else if (sid == "FE") {
        snm = "외국ETF";
    } else if (sid == "FS") {
        snm = "외국주권";
    }
    return snm;
};


