/*
 * 사유찾기
 */
/**
 * @method
 * @name fn_PopFindLstRsnCd
 * @description desc
 * @param {string} pRsnCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_PopFindLstRsnCd = async function(pRsnCd) {
    var vRsnNm = "사유선택";
    if (pRsnCd == scwin.RSNCD_SUSP) {
        vRsnNm = "매매거래정지사유 선택";
    } else if (pRsnCd == scwin.RSNCD_ADM_DESIGN) {
        vRsnNm = "관리종목지정사유 선택";
    } else if (pRsnCd == scwin.RSNCD_ADM_RELEAS) {
        vRsnNm = "관리종목지정해제사유 선택";
    } else if (pRsnCd == scwin.RSNCD_ICR_DESIGN) {
        vRsnNm = "투자주의환기지정사유 선택";
    } else if (pRsnCd == scwin.RSNCD_ICR_RELEAS) {
        vRsnNm = "투자주의환기지정해제사유 선택";
    }
    await $c.frame.CreateDialogFrame("DLG_LST_RSN_CD", "../listingcommon/ULDSTF92007.gfm", vRsnNm, 10, 10, 515 + 5, 315 + 30, "window");
};


