MSG_SYMBL_DOUBLE_INPUT = "";

/**
 * 입력한 심볼중복여부 체크
 */
/**
 * @method
 * @name fn_chkCorpSymblDoubleInput
 * @description desc
 * @param {string} symbl desc
 * @param {string} symblCd desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_chkCorpSymblDoubleInput = function(symbl, symblCd, dtsObj) {
    return scwin.fn_chkSymblDoubleInput('1', symbl, symblCd, dtsObj);
};
/**
 * @method
 * @name fn_chkIsuSymblDoubleInput
 * @description desc
 * @param {string} symbl desc
 * @param {string} symblCd desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_chkIsuSymblDoubleInput = function(symbl, symblCd, dtsObj) {
    return scwin.fn_chkSymblDoubleInput('2', symbl, symblCd, dtsObj);
};
/**
 * @method
 * @name fn_chkSymblDoubleInput
 * @description desc
 * @param {string} symblTyp desc
 * @param {string} symbl desc
 * @param {string} symblCd desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_chkSymblDoubleInput = function(symblTyp, symbl, symblCd, dtsObj) {
    var str = "";
    if (symblTyp == '1') {
        str = '영문회사';
    } else if (symblTyp == '2') {
        str = '영문종목';
    }
    if (symbl == "") {
        alert("[" + str + "심볼]을 입력하세요.");
        return false;
    }
    if (symblTyp == '1') {
        if (symbl.length >= 7) {
            alert("[" + str + "심볼]을 6자리이내로 입력하세요.");
            return false;
        }
    } else if (symblTyp == '2') {
        if (symbl.length >= 8) {
            alert("[" + str + "심볼]을 7자리이내로 입력하세요.");
            return false;
        }
    }
    var url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + DIV_R_CHK_SYMBL;
    url += "&SYMBL_TYP=" + symblTyp;
    url += "&SYMBL=" + symbl;
    dts_Symbl.DataID = encodeURI(url);
    dts_Symbl.Reset();


    //alert('[dts_Symbl.CountRow]'+dtsObj.CountRow);
    var vCd = dtsObj.getCellData(1, "CD");
    var vNm = dtsObj.getCellData(1, "NM");
    if (dtsObj.getTotalRow() > 0 && symblCd != vCd) {
        var msg = "" + "이미 지정되어 있는 " + str + "심볼을 입력하셨습니다.\n" + "다시 확인 하시고 입력 해 주십시오.\n\n" + "중복 데이터 내용 : \n" + "[" + vCd + "]" + vNm + " \n";
        scwin.MSG_SYMBL_DOUBLE_INPUT = msg;
        return false;
    } else {
        var msg = "입력한 " + str + "심볼을 사용할 수 있습니다";
        scwin.MSG_SYMBL_DOUBLE_INPUT = msg;
        return true;
    }
};




/*
 * panel에 포함된 editable controls 들을 readonly, disable 상태로 변환한다.
 */
/**
 * @method
 * @name fn_setPanReadOnly
 * @description desc
 * @param {string} o desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setPanReadOnly = function(o) {
    var e;
    if (o != undefined) {
        for (var i = 0; i < o.children.length; i++) {
            e = o.children.item(i);
            if (e.tagName.toUpperCase() == "OBJECT") {
                switch (e.classid) {
                    case "clsid:D7779973-9954-464e-9708-DA774CA50E13": // maskedit
                        e.setReadOnly(true);
                        break;
                    case "clsid:BB4533A0-85E0-4657-9BF2-E8E7B100D47E": // combo
                        e.setDisabled(true);
                        break;
                    case "clsid:F73C0958-D8FE-43a5-9BB0-0F651C5A2BCC": // radio
                        e.setDisabled(true);
                        break;
                    case "clsid:1455BE02-C41B-4115-B21C-32380507DC8F": // textarea
                        e.setReadOnly(true);
                        break;
                    case "clsid:71E7ACA0-EF63-4055-9894-229B056E9C31": // grid
                        e.setDisabled(true);
                        break;
                }
            } else if (e.tagName.toUpperCase() == "INPUT") {
                switch (e.type.toUpperCase()) {
                    case "TEXT":
                        e.setReadOnly(true); //"readonly";
                        break;
                    case "CHECKBOX":
                        e.setDisabled(true); //"disabled";
                        break;
                }
            } else if (e.tagName.toUpperCase() == "SELECT") {
                switch (e.type.toUpperCase()) {
                    case "SELECT-ONE":
                        e.setDisabled(true); //"disabled";
                        break;
                }
            }
        }
    }
};
