 * @name isInArr
 * @description desc
 * @param {string} o desc
 * @param {string} ec desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isInArr = function(o, ec) {
    for (var i = 0; i < ec.length; i++) {
        if (o == ec[i]) {
            return true;
        }
    }
    return false;
};


