/*
 * 팝업창에서 선택한 사항이 이미 DataSet에 있는지 검증한다.
 */
/**
 * @method
 * @name fn_isNewValueForDataSet
 * @description desc
 * @param {string} dts desc
 * @param {string} colName desc
 * @param {string} checkValue desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_isNewValueForDataSet = function(dts, colName, checkValue) {
    for (var i = 1; i <= dts.getTotalRow(); i++) {
        if (dts.getCellData(i, colName) == checkValue) {
            alert("이미 선택하신 사유가 있습니다.");
            return false;
        }
    }
    return true;
};


