 * @param {string} dts desc
 * @param {string} rowIndex desc
 * @param {string} colNameDdTm desc
 * @param {string} colNameDd desc
 * @param {string} colNameTm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.mergeDtsDataForDdTm = function(dts, rowIndex, colNameDdTm, colNameDd, colNameTm) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    dts.setCellData(rowIndex, colNameDdTm, /*ORG SRC: dts.setNameString(rowIndex, colNameDdTm, dts.NameString(rowIndex, colNameDdTm) = );*/ X = X);
    dts.getCellData(rowIndex, colNameDd) + dts.getCellData(dts.getFocusedRowIndex(), colNameTm);
};


/*
 * 일자 + 시간 데이타를 일자,시간으로 나누는 함수
 * nullable : Y 이면 데이타가 없으수도 있음.
 */
/**
 * @method
 * @name divideDtsDataForDdTm
 * @description desc
 * @param {string} dts desc
 * @param {string} rowIndex desc
 * @param {string} isNullable desc
 * @param {string} colNameDdTm desc
 * @param {string} colNameDd desc
 * @param {string} colNameTm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.divideDtsDataForDdTm = function(dts, rowIndex, isNullable, colNameDdTm, colNameDd, colNameTm) {
    var tmpDdTm = "";
    tmpDdTm = dts.getCellData(rowIndex, colNameDdTm);
    if (isNullable == "Y" && tmpDdTm.length < 7) return;
    if (
        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************
        tmpDdTm.length > 7, tmpDdTm.substring(0, 8)) dts.setCellData(rowIndex, colNameDd);
    if (
        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************
        tmpDdTm.length > 8, tmpDdTm.substring(8)) dts.setCellData(rowIndex, colNameTm);
};


/*
 * 일자,시간 체크 함수
 * isCheckCurDate : 오늘 날짜를 포함해서 비교를 할지 여부 ( 유가 : 미포함, 코스닥 : 포함 )
 */
/**
 * @method
 * @name checkDdTm
 * @description desc
 * @param {string} gubun desc
 * @param {string} obj desc
 * @param {string} msg desc
 * @param {string} includeCurDate desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkDdTm = function(gubun, obj, msg, includeCurDate) {
    if (gubun == "DD") {
        if (obj.text.length != 8) {
            alert("[" + msg + "일]을 정확히 입력하세요.");
            obj.focus();
            return false;
        }
        var vCurDate = $c.ut.cGetToday("yyyymmdd");
        if (includeCurDate) {
            if (vCurDate > $c.stf.getObjectValue(obj)) {
                alert("[" + msg + "일]을 현재일 이후로 입력하세요.");
                obj.focus();
                return false;
            }
        } else {
            if (vCurDate >= $c.stf.getObjectValue(obj)) {
                alert("[" + msg + "일]을 익일 이후로 입력하세요.");
                obj.focus();
                return false;
            }
        }
    } else if (gubun == "TM") {
        if (obj.text.length == 0) return true;
        if (obj.text.length != 6) {
            alert("[" + msg + "시간]을 [시,분,초]까지 정확히 입력하세요.");
            obj.focus();
            return false;
        }
        var tmp = obj.getText();
        if (eval(tmp.substring(0, 2)) > 23) {
            alert("[" + msg + "시간중 시]를 정확히 입력하세요.");
            obj.focus();
            return false;
        }
        if (eval(tmp.substring(2, 4)) > 59) {
            alert("[" + msg + "시간중 분]을 정확히 입력하세요.");
            obj.focus();
            return false;
        }
        if (eval(tmp.substring(4)) > 59) {
            alert("[" + msg + "시간중 초]를 정확히 입력하세요.");
            obj.focus();
            return false;
        }
    } else if (gubun == "TM2") {
        if (obj.text.length == 0) return true;
        if (obj.text.length != 4) {
            alert("[" + msg + "시간]을 [시,분]까지 정확히 입력하세요.");
            obj.focus();
            return false;
        }
        var tmp = obj.getText();
        if (eval(tmp.substring(0, 2)) > 23) {
            alert("[" + msg + "시간중 시]를 정확히 입력하세요.");
            obj.focus();
            return false;
        }
        if (eval(tmp.substring(2, 4)) > 59) {
            alert("[" + msg + "시간중 분]을 정확히 입력하세요.");
            obj.focus();
            return false;
        }
    }
    return true;
};



