/*
 * 그리드에서 수정할때와  신규등록시 변경전 데이타의 ROWCONT 구하기
 */
/**
 * @method
 * @name fn_getRowIdx
 * @description desc
 * @param {string} vKey desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getRowIdx = function(vKey, dtsObj) {
    var vRow;
    if (vKey == "") {
        vRow = dtsObj.getTotalRow();
    } //신규등록시 
    else if (vKey != "") {
        vRow = dtsObj.getFocusedRowIndex() - 1;
    } //수정시 

    return vRow;
};


/*
 * 관리종목지정 관련해서
 * 현재 업무를 저장할수 있는지 여부를 판단해줌
 */
/**
 * @method
 * @name fn_getMstStatus
 * @description desc
 * @param {string} param_Dts desc
 * @param {string} tpCd desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getMstStatus = function(param_Dts, tpCd, obj) {
    var url = "/administrativeIssue.do?method=searchAdministrativeIssue" + "&DIV_IDX=" + scwin.DIV_IDX_ADMISU_MST + "&TRS_IDX=" + scwin.TRS_IDX_NEWSEL + "&ISUR_CD=" + Isur_cd;
    param_Dts.DataID = encodeURI(url);
    param_Dts.reset();
    var isFlag = false;
    var type = param_Dts.getCellData(1, "ADMISU_DESIGN_BZ_TP_CD");
    var maxDate = param_Dts.getCellData(1, "MKTACT_ENFORCE_DD");
    /*
	관리종목지정업무구분코드
	0:관리종목지정
	1:관리종목사유변경
	2:관리종목사유및유의사항변경
    3:유의사항변경
    4:관리종목지정해제
	5:상장폐지기준적용유예
    6:상장폐지기준적용유예기간변경
	*/

    if (maxDate >= $c.stf.getObjectValue(obj)) {
        alert($c.stf.getMessageParam("MSG-0020", ""));
        return false;
    }

    // 지정일 경우는 직전이 해제여야 함
    if (tpCd == '0') {
        if (type == '4' || type == null) isFlag = true;
    }
    // 해제일경우는 직전이 해제가 아니여야 함
    else if (tpCd == '4' || tpCd == '5') {
        if (type != '4' && type != null) isFlag = true;
    }
    // 상장폐지기준적용유예일 경우는 직전이 유예여야 함
    else if (tpCd == '6') {
        if (type == '5') isFlag = true;
    }
    // 기타는 직전이 해제만 아니면됨. 
    else if (tpCd == '1' || tpCd == '2' || tpCd == '3') {
        if (type != '4' && type != null) isFlag = true;
    }
    if (!isFlag) alert($c.stf.getMessageParam("MSG-0021", ""));
    return isFlag;
};


