 */
scwin.fn_check_delete_discls = function(dtsObj, gBzProcsNo) {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=BZ_PROCS_NO_CHECK_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.listingcommonbiz.select.bzprocsno.disclsstatcd" + "&{P}param01=" + gBzProcsNo;
    dtsObj.DataID = encodeURI(url);
    dtsObj.reset();
    var vPROCS_DDTM = dtsObj.getCellData(1, "DISCLS_PROCS_DDTM");
    if (vPROCS_DDTM == "") {
        return true;
    } else {
        alert("본 건의 시장안내공시가 " + vPROCS_DDTM + "에  이미 승인되어 삭제 하실 수 없습니다.");
        return false;
    }
};
/**
 * @method
 * @name fn_check_bz_doubleinput
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} gIsurCd desc
 * @param {string} gChdDD desc
 * @param {string} gbzProcsNo desc
 * @param {string} gListBzTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_check_bz_doubleinput = function(dtsObj, gIsurCd, gChdDD, gbzProcsNo, gListBzTpCd) {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=BZ_PROCS_NO_CHECK_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.listingcommonbiz.select.bzprocsno.doublinputchek.condition" + "&{P}param01=" + gIsurCd + "&{P}param02=" + gChdDD + "&{P}param03=" + gbzProcsNo + "&{P}param04=" + gListBzTpCd;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    var vPROCS_DDTM = dtsObj.getCellData(1, "DISCLS_PROCS_DDTM");
    var vPROCS_STAT_CD = dtsObj.getCellData(1, "DISCLS_PROCS_STAT_CD");
    if (vPROCS_DDTM == "") {
        return true;
    } else {
        alert("[" + vPROCS_STAT_CD + "]건으로 " + vPROCS_DDTM + "에  이미 입력되어있습니다.");
        return false;
    }
    var gCnt = dtsObj.getCellData(1, "CNT");
    if (gCnt > 0) {
        alert("상장(변경/조치)일자가 동일한 시장안내정보가 이미 입력되었습니다");
        return false;
    } else {
        return true;
    }
};




