};



/**
 *  입력한일자가 영업일인지 체크
 * fn_TrHoldyYn
 */
/**
 * @method
 * @name fn_eng_symbl_check
 * @description desc
 * @param {string} pIsurSymbl desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_eng_symbl_check = function(pIsurSymbl) {
    var bFlag = true;
    for (var i = 0; i < pIsurSymbl.length; i++) {
        if (!((pIsurSymbl.charCodeAt(i) >= 48 && pIsurSymbl.charCodeAt(i) <= 57) ||
                (pIsurSymbl.charCodeAt(i) >= 65 && pIsurSymbl.charCodeAt(i) <= 90) ||
                (pIsurSymbl.charCodeAt(i) >= 97 && pIsurSymbl.charCodeAt(i) <= 122) ||
                (pIsurSymbl.charCodeAt(i) == 45))) {
            alert("영문회사 심볼은 영문, 숫자, 하이픈(-)만 입력 가능합니다.");
            bFlag = false;
            break;
        }
    }
    return bFlag;
};
